package com.gameaggregator.incidentservice.domain;import jakarta.persistence.*;import java.util.UUID;@Entity @Table(name="incident_affected_services",uniqueConstraints=@UniqueConstraint(columnNames={"incidentId","serviceName"})) public class IncidentAffectedService{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID incidentId;@Column(nullable=false)public String serviceName;protected IncidentAffectedService(){}public IncidentAffectedService(UUID i,String s){incidentId=i;serviceName=s;}}